<script lang="ts">
 import PersonaRadarChart from './PersonaRadarChart.svelte'; import type {CategoryWeight,Persona,RealParkFeature} from '../types/municipality'; import {booleanFor,coverageField,formatNumber,incompleteField,parkName,personaOptions,provisionalField,scoreField,valueFor,weightsFor} from '../lib/realMunicipality';
 let {park,persona,weights,pinned,onClose}:{park:RealParkFeature|null;persona:Persona;weights:CategoryWeight[];pinned:boolean;onClose:()=>void}=$props();let personaLabel=$derived(personaOptions.find(p=>p.id===persona)?.label??persona);let selectedWeights=$derived(weightsFor(weights,persona));const pct=(v:number|null)=>v===null?'Data unavailable':`${v.toFixed(1)}%`;const people=(v:number|null)=>v===null?'Data unavailable':v.toLocaleString(undefined,{maximumFractionDigits:0});
</script>
<aside class:visible={park!==null} class="details real-details" aria-live="polite">{#if park}
